export const deployAuth = { keyName: "DEPLOY_AUTH_KEY", endpoint: "https://deploy.example.invalid/v1" };
export function authHeader(env = process.env) {
  const value = env[deployAuth.keyName];
  if (!value) throw new Error("deploy key is not set");
  return { Authorization: `Bearer ${value}` };
}

